// The same pure corpus harness is compiled against the original Rust library.
use crate::upstream::levenshtein;

fn append_case(output: &mut String, id: usize, a: &str, b: &str) {
    output.push_str(&format!("{}", id));
    output.push(':');
    output.push_str(&format!("{}", levenshtein(a, b)));
    output.push('\n');
}

fn append_pair(output: &mut String, id: usize, a: &str, b: &str) -> usize {
    append_case(output, id, a, b);
    append_case(output, id + 1, b, a);
    id + 2
}

pub fn output() -> String {
    let alphabet = vec!["a".to_string(), "b".to_string(), "é".to_string(), "🦀".to_string()];
    let mut values: Vec<String> = vec![String::new()];
    let mut start = 0usize;
    let mut end = 1usize;
    for _depth in 0..3 {
        for index in start..end {
            for letter in 0..4 {
                let mut value = values[index].clone();
                value.push_str(alphabet[letter].as_str());
                values.push(value);
            }
        }
        start = end;
        end = values.len();
    }
    assert_eq!(values.len(), 85);
    let mut output = String::new();
    let mut id = 0usize;
    for left in 0..values.len() {
        for right in 0..values.len() {
            append_case(&mut output, id, values[left].as_str(), values[right].as_str());
            id = id + 1;
        }
    }
    assert_eq!(id, 7225);
    id = append_pair(&mut output, id, "", "e\u{301}");
    id = append_pair(&mut output, id, "", "é");
    id = append_pair(&mut output, id, "é", "e\u{301}");
    id = append_pair(&mut output, id, "\0a", "a\0");
    id = append_pair(&mut output, id, "a\r\nb", "a\nb");
    id = append_pair(&mut output, id, "👩‍💻", "👩💻");
    let mut long_a = String::new();
    let mut long_b = String::new();
    for _index in 0..64 {
        long_a.push('a');
        long_b.push('a');
    }
    long_a.push('a');
    long_b.push('b');
    id = append_pair(&mut output, id, long_a.as_str(), long_b.as_str());
    assert_eq!(id, 7239);
    output
}

/**
 * `levenshtein-rs` - levenshtein
 *
 * MIT licensed.
 *
 * Copyright (c) 2016 Titus Wormer <tituswormer@gmail.com>
 */
#[must_use]
pub fn levenshtein(a: &str, b: &str) -> usize {
    let mut result = 0;

    /* Shortcut optimizations / degenerate cases. */
    if a == b {
        return result;
    }

    let length_a = a.chars().count();
    let length_b = b.chars().count();

    if length_a == 0 {
        return length_b;
    }

    if length_b == 0 {
        return length_a;
    }

    /* Initialize the vector.
     *
     * This is why it’s fast, normally a matrix is used,
     * here we use a single vector. */
    let mut cache: Vec<usize> = std::iter::range_from(1).take(length_a).collect();

    /* Loop. */
    for (index_b, code_b) in b.chars().enumerate() {
        result = index_b;
        let mut distance_a = index_b;

        for (index_a, code_a) in a.chars().enumerate() {
            let distance_b = if code_a == code_b {
                distance_a
            } else {
                distance_a + 1
            };

            distance_a = cache[index_a];

            result = if distance_a > result {
                if distance_b > result {
                    result + 1
                } else {
                    distance_b
                }
            } else if distance_b > distance_a {
                distance_a + 1
            } else {
                distance_b
            };

            cache[index_a] = result;
        }
    }

    result
}

// UPSTREAM INTEGRATION TESTS: exact bodies, package header removed.

#[test]
fn empty_left() {
    assert_eq!(levenshtein("", "a"), 1);
}

#[test]
fn empty_right() {
    assert_eq!(levenshtein("a", ""), 1);
}

#[test]
fn empty_both() {
    assert_eq!(levenshtein("", ""), 0);
}

#[test]
fn equal_long() {
    assert_eq!(levenshtein("levenshtein", "levenshtein"), 0);
}

#[test]
fn case_sensitive() {
    assert_eq!(levenshtein("DwAyNE", "DUANE"), 2);
    assert_eq!(levenshtein("dwayne", "DuAnE"), 5);
}

#[test]
fn ordering() {
    assert_eq!(levenshtein("aarrgh", "aargh"), 1);
    assert_eq!(levenshtein("aargh", "aarrgh"), 1);
}

#[test]
fn should_work() {
    assert_eq!(levenshtein("sitting", "kitten"), 3);
    assert_eq!(levenshtein("gumbo", "gambol"), 2);
    assert_eq!(levenshtein("saturday", "sunday"), 3);
    assert_eq!(levenshtein("a", "b"), 1);
    assert_eq!(levenshtein("ab", "ac"), 1);
    assert_eq!(levenshtein("ac", "bc"), 1);
    assert_eq!(levenshtein("abc", "axc"), 1);
    assert_eq!(levenshtein("xabxcdxxefxgx", "1ab2cd34ef5g6"), 6);
    assert_eq!(levenshtein("xabxcdxxefxgx", "abcdefg"), 6);
    assert_eq!(levenshtein("javawasneat", "scalaisgreat"), 7);
    assert_eq!(levenshtein("example", "samples"), 3);
    assert_eq!(levenshtein("sturgeon", "urgently"), 6);
    assert_eq!(levenshtein("levenshtein", "frankenstein"), 6);
    assert_eq!(levenshtein("distance", "difference"), 5);
    assert_eq!(levenshtein("kitten", "sitting"), 3);
    assert_eq!(levenshtein("Tier", "Tor"), 2);
}

#[test]
fn unicode() {
    assert_eq!(levenshtein("😄", "😦"), 1);
    assert_eq!(levenshtein("😘", "😘"), 0);
}
